const Toast={show(msg,type="info",duration=3500){let container=document.getElementById("bb-toast");if(!container){container=document.createElement("div");container.id="bb-toast";document.body.appendChild(container)}const icons={success:"check_circle",error:"error",info:"info",warning:"warning"};const colors={success:"#34d399",error:"#f87171",info:"#d4af37",warning:"#fbbf24"};const toast=document.createElement("div");toast.className=`bb-toast bb-toast--${type}`;toast.innerHTML=`\n      <span class="material-symbols-outlined" style="color:${colors[type]}">${icons[type]}</span>\n      <span>${msg}</span>\n      <button onclick="this.parentElement.remove()" style="margin-left:auto;color:var(--bb-text-subtle);font-size:1.2rem;line-height:1;">&times;</button>\n    `;container.appendChild(toast);setTimeout(()=>{toast.style.opacity="0";toast.style.transform="translateY(8px)";toast.style.transition="0.3s";setTimeout(()=>toast.remove(),300)},duration)}};const Modal={show({title:title="",body:body="",confirmLabel:confirmLabel="Confirmer",cancelLabel:cancelLabel="Annuler",onConfirm:onConfirm=null,danger:danger=false}){const backdrop=document.createElement("div");backdrop.className="bb-modal-backdrop";backdrop.innerHTML=`\n      <div class="bb-modal" role="dialog" aria-modal="true">\n        <h3 style="font-family:var(--font-display);font-size:1.25rem;font-weight:700;margin-bottom:0.75rem">${title}</h3>\n        <p style="color:var(--bb-text-muted);font-size:0.9375rem;margin-bottom:1.5rem">${body}</p>\n        <div style="display:flex;gap:0.75rem;justify-content:flex-end">\n          <button class="bb-btn bb-btn-ghost" id="bb-modal-cancel">${cancelLabel}</button>\n          <button class="bb-btn ${danger?"bb-btn-danger":"bb-btn-gold"}" id="bb-modal-confirm">${confirmLabel}</button>\n        </div>\n      </div>\n    `;document.body.appendChild(backdrop);backdrop.querySelector("#bb-modal-cancel").onclick=()=>backdrop.remove();backdrop.querySelector("#bb-modal-confirm").onclick=()=>{onConfirm&&onConfirm();backdrop.remove()};backdrop.onclick=e=>{if(e.target===backdrop)backdrop.remove()}}};document.addEventListener("DOMContentLoaded",()=>{const hamburger=document.querySelector(".bb-hamburger:not(#bb-nav-toggle)");const sidebar=document.querySelector(".bb-sidebar");const overlay=document.querySelector(".bb-sidebar-overlay");if(hamburger&&sidebar){hamburger.addEventListener("click",()=>{sidebar.classList.toggle("bb-sidebar--open")});overlay&&overlay.addEventListener("click",()=>sidebar.classList.remove("bb-sidebar--open"))}checkAdminDashboard();if(document.querySelector(".bb-quiz-page")){window.addEventListener("beforeunload",e=>{e.preventDefault();e.returnValue=""});document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden"){const warn=document.getElementById("bb-cheat-warning");if(warn){warn.style.backgroundColor="rgba(239,68,68,0.2)";warn.style.borderColor="rgba(239,68,68,0.5)"}Toast.show("⚠️ Vous avez quitté la page — votre quiz peut être annulé.","error",5e3)}})}const timerEl=document.getElementById("bb-timer");if(timerEl)initTimer(timerEl)});window.QuizTimer={_interval:null,_seconds:0,_el:null,init(el,initialSeconds=900){this._el=el;this._seconds=initialSeconds;this.stop();this._render()},start(){if(this._interval)return;this._render();this._interval=setInterval(()=>{if(this._seconds<=0){this.stop();Toast.show("Temps écoulé !","warning");if(typeof finishQuiz==="function")finishQuiz()}else{this._seconds--;this._render()}},1e3)},stop(){if(this._interval){clearInterval(this._interval);this._interval=null}},reset(seconds){this.stop();this._seconds=seconds;this.start()},_render(){if(!this._el)return;const m=Math.floor(this._seconds/60);const s=this._seconds%60;this._el.textContent=`${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;this._el.classList.toggle("bb-timer--warning",this._seconds<=10&&this._seconds>5);this._el.classList.toggle("bb-timer--danger",this._seconds<=5)}};function initTimer(el){window.QuizTimer.init(el,parseInt(el.dataset.seconds||900,10))}const Confirm={ask(title,body,onConfirm,danger=false){Modal.show({title:title,body:body,onConfirm:onConfirm,danger:danger})}};const FormGuard={_initialData:null,watch(formId){const form=document.getElementById(formId);if(!form)return;this._initialData=new FormData(form);window.onbeforeunload=e=>{const currentData=new FormData(form);let changed=false;for(let[key,value]of this._initialData.entries()){if(currentData.get(key)!==value){changed=true;break}}if(changed){e.preventDefault();e.returnValue=""}}}};function changeRole(userId,newRole){Confirm.ask("Changer le rôle",`Voulez-vous vraiment attribuer le rôle <strong>${newRole}</strong> à cet utilisateur&nbsp;?`,()=>{const row=document.querySelector(`[data-uid="${userId}"]`)||document.querySelector(`[data-user-id="${userId}"]`);if(row){const badge=row.querySelector(".bb-role-badge");if(badge){badge.textContent=newRole;badge.className=`bb-badge bb-role-badge role-${newRole.toLowerCase()}`}}Toast.show(`Rôle attribué : ${newRole}`,"success")})}function shareWinners(){Confirm.ask("Partager la liste officielle","La liste des gagnants sera publiée et partagée officiellement. Cette action est irréversible.",()=>Toast.show("Liste officielle partagée avec succès !","success"))}function confirmLogout(){Confirm.ask("Déconnexion","Voulez-vous vraiment vous déconnecter ?",()=>{sessionStorage.clear();window.location.href=(window.location.pathname.includes("/admin/")?"../":"")+"connexion.html"},true)}function updateNotificationBadge(count){const bells=document.querySelectorAll(".material-symbols-outlined");bells.forEach(icon=>{if(icon.textContent==="notifications_active"||icon.textContent==="notifications"){const btn=icon.parentElement;btn.style.cursor="pointer";btn.onclick=()=>{const prefix=window.location.pathname.includes("/admin/")?"../":"";window.location.href=prefix+"notifications.html"};let badge=btn.querySelector(".bb-notif-badge");if(!badge&&count>0){badge=document.createElement("span");badge.className="bb-notif-badge";badge.style.cssText=`\n                    position: absolute;\n                    top: -2px;\n                    right: -2px;\n                    background: var(--bb-danger);\n                    color: white;\n                    font-size: 10px;\n                    font-weight: 800;\n                    padding: 2px 5px;\n                    border-radius: 10px;\n                    border: 2px solid var(--bb-surface);\n                    line-height: 1;\n                    pointer-events: none;\n                `;btn.style.position="relative";btn.appendChild(badge)}if(badge){if(count>0){badge.textContent=count>99?"99+":count;badge.style.display="block"}else{badge.style.display="none"}}}})}function checkAdminDashboard(){const token=sessionStorage.getItem("bb_token");if(!token)return;try{const payload=JSON.parse(atob(token.split(".")[1]));if(payload.role==="Admin"||payload.role==="Superadmin1"||payload.role==="Superadmin"){const headerActions=document.querySelector(".bb-header__actions");if(headerActions&&!document.getElementById("admin-dash-btn")){const prefix=window.location.pathname.includes("/admin/")?"":"admin/";const btn=document.createElement("a");btn.id="admin-dash-btn";btn.href=prefix+"admin-dashboard.html";btn.className="bb-btn bb-btn-outline bb-btn-sm";btn.style.marginRight="0.5rem";btn.style.display="inline-flex";btn.style.alignItems="center";btn.style.gap="0.25rem";btn.innerHTML='<span class="material-symbols-outlined" style="font-size:1.1rem">admin_panel_settings</span> <span class="nav-text">Admin</span>';headerActions.insertBefore(btn,headerActions.firstChild)}}}catch(e){console.error("Session error:",e)}}const originalFetch=window.fetch;window.fetch=async(...args)=>{try{const response=await originalFetch(...args);if(response.status===503&&!window.location.pathname.includes("maintenance.html")){const data=await response.clone().json();if(data.maintenance){window.location.href=(window.location.pathname.includes("/admin/")?"../":"")+"maintenance.html"}}return response}catch(err){throw err}};async function loadPublicStats(){const containers={totalUsers:document.querySelector('[data-stat="totalUsers"]'),totalQuizzes:document.querySelector('[data-stat="totalQuizzes"]'),avgAccuracy:document.querySelector('[data-stat="avgAccuracy"]'),cheatRate:document.querySelector('[data-stat="cheatRate"]')};try{const res=await fetch("/api/stats/public");const data=await res.json();if(data.totalUsers!==undefined&&containers.totalUsers){containers.totalUsers.textContent=data.totalUsers.toLocaleString()+(data.totalUsers>1e3?"+":"")}if(data.totalQuizzes!==undefined&&containers.totalQuizzes){containers.totalQuizzes.textContent=data.totalQuizzes.toLocaleString()+(data.totalQuizzes>1e3?"+":"")}if(data.avgAccuracy!==undefined&&containers.avgAccuracy){containers.avgAccuracy.textContent=data.avgAccuracy+"%"}if(data.cheatRate!==undefined&&containers.cheatRate){containers.cheatRate.textContent=data.cheatRate}}catch(e){console.error("Stats load error",e)}}async function resetSystemData(){Confirm.ask("RÉINITIALISATION COMPLÈTE",'⚠️ <span style="color:var(--bb-danger);font-weight:700">ATTENTION:</span> Cette action supprimera TOUS les utilisateurs (sauf vous), tous les scores et tous les logs. Les questions et catégories resteront intactes. Voulez-vous continuer ?',async()=>{const token=sessionStorage.getItem("bb_token");try{const res=await fetch("/api/admin/system/reset-data",{method:"POST",headers:{Authorization:`Bearer ${token}`}});const data=await res.json();if(res.ok){Toast.show(data.message,"success",5e3);setTimeout(()=>window.location.reload(),2e3)}else{Toast.show(data.message||"Erreur lors du reset.","error")}}catch(e){Toast.show("Erreur de connexion.","error")}},true)}window.loadPublicStats=loadPublicStats;window.resetSystemData=resetSystemData;window.Toast=Toast;window.Modal=Modal;window.Confirm=Confirm;window.FormGuard=FormGuard;window.updateNotificationBadge=updateNotificationBadge;window.confirmLogout=confirmLogout;